import ast, sys
for f in ('planner.py','controller.py','main.py'):
    tree = ast.parse(open(f).read())
    names = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Name): names.add(node.id)
        if isinstance(node, ast.Attribute): pass
    src = open(f).read()
    imported = []
    for node in tree.body:
        if isinstance(node, ast.Import):
            for a in node.names: imported.append(a.asname or a.name.split('.')[0])
        if isinstance(node, ast.ImportFrom):
            for a in node.names: imported.append(a.asname or a.name)
    unused = [i for i in imported if src.count(i) < 2]
    print(f, 'unused imports:', unused)
